def semver_sort(versions):
    def parse_version(v):
        # Split build metadata (after +)
        if '+' in v:
            v, build = v.split('+', 1)
        else:
            build = ''

        # Split pre-release (after -)
        if '-' in v:
            core, prerelease = v.split('-', 1)
        else:
            core = v
            prerelease = None

        # Parse core version (MAJOR.MINOR.PATCH)
        parts = core.split('.')
        major = int(parts[0])
        minor = int(parts[1]) if len(parts) > 1 else 0
        patch = int(parts[2]) if len(parts) > 2 else 0

        # Parse pre-release identifiers
        if prerelease is not None:
            prerelease_parts = prerelease.split('.')
        else:
            prerelease_parts = None

        return (major, minor, patch, prerelease_parts)

    def prerelease_key(prerelease_parts):
        # None means no pre-release, which sorts after any pre-release
        if prerelease_parts is None:
            return (1,)  # Sorts after (0, ...)

        # Convert each identifier to a comparable form
        key = [0]  # 0 means this has a pre-release
        for identifier in prerelease_parts:
            if identifier.isdigit():
                # All-digit identifiers: compare numerically, and sort before non-digit
                key.append((0, int(identifier)))
            else:
                # Non-digit identifiers: compare lexicographically, and sort after digit
                key.append((1, identifier))

        return tuple(key)

    def sort_key(item):
        index, version = item
        major, minor, patch, prerelease_parts = parse_version(version)
        return (major, minor, patch, prerelease_key(prerelease_parts), index)

    # Add index to maintain stability (preserve order for equal versions)
    indexed_versions = list(enumerate(versions))
    sorted_versions = sorted(indexed_versions, key=sort_key)

    return [v for _, v in sorted_versions]

